'use strict';
// Verifies the saved pipeline artifacts and writes answer.json from them.
const fs = require('fs');
const path = require('path');

const dir = __dirname;
const readNum = (name) => {
  const p = path.join(dir, name);
  if (!fs.existsSync(p)) throw new Error(`missing required file: ${name}`);
  const raw = fs.readFileSync(p, 'utf8').trim();
  if (raw === '') throw new Error(`empty file: ${name}`);
  const n = Number(raw);
  if (!Number.isFinite(n)) throw new Error(`non-numeric value in ${name}: ${JSON.stringify(raw)}`);
  return n;
};

const seed = readNum('seed.txt');
const stage1 = readNum('stage1.txt');
const stage2 = readNum('stage2.txt');
const stage3 = readNum('stage3.txt');

const checks = [
  ['stage1 = seed + 2', stage1 === seed + 2],
  ['stage2 = stage1^2', stage2 === stage1 * stage1],
  ['stage3 = stage2 - 4', stage3 === stage2 - 4],
];
let ok = true;
for (const [label, passed] of checks) {
  console.log(`${passed ? 'PASS' : 'FAIL'}: ${label}`);
  if (!passed) ok = false;
}
if (!ok) {
  console.error('verification failed; answer.json not written');
  process.exit(1);
}

const answer = { stage1, stage2, stage3 };
fs.writeFileSync(path.join(dir, 'answer.json'), JSON.stringify(answer) + '\n');

// Re-read answer.json and confirm keys/values/types match the saved stage files.
const written = JSON.parse(fs.readFileSync(path.join(dir, 'answer.json'), 'utf8'));
const keys = Object.keys(written).sort().join(',');
if (keys !== 'stage1,stage2,stage3') throw new Error(`unexpected answer.json keys: ${keys}`);
for (const k of ['stage1', 'stage2', 'stage3']) {
  if (typeof written[k] !== 'number') throw new Error(`answer.json ${k} is not a number`);
  if (written[k] !== readNum(`${k}.txt`)) throw new Error(`answer.json ${k} does not match ${k}.txt`);
}
console.log('PASS: answer.json keys/values match saved stage files');
console.log('answer.json =', JSON.stringify(written));

